'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is a `from` method for creating a typed array from an array-like object or iterable', function test( t ) {
	t.strictEqual( hasProp( Float64Array, 'from' ), true, 'has property' );
	t.strictEqual( isFunction( Float64Array.from ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if provided a second argument which is not a function', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Float64Array.from( [], value );
		};
	}
});

tape( 'the method throws an error if provided a second argument which is not a function (thisArg)', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Float64Array.from( [], value, {} );
		};
	}
});

tape( 'the method returns an empty typed array if provided an empty array', function test( t ) {
	var arr;
	var out;

	arr = [];
	out = Float64Array.from( arr );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.strictEqual( out.length, 0, 'returns expected value' );
	t.end();
});

tape( 'the method creates a typed array from an array-like object', function test( t ) {
	var arr;
	var out;

	arr = [ 1.0, 2.0, 3.0 ];
	out = Float64Array.from( arr );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.strictEqual( out.length, 3, 'returns expected value' );
	t.strictEqual( out[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 3.0, 'returns expected value' );
	t.end();
});

tape( 'the method creates a typed array from another typed array', function test( t ) {
	var src;
	var out;

	src = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = Float64Array.from( src );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.notEqual( out, src, 'returns a new instance' );
	t.strictEqual( out.length, 3, 'returns expected value' );
	t.strictEqual( out[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 3.0, 'returns expected value' );
	t.end();
});

tape( 'the method supports a map function', function test( t ) {
	var arr;
	var out;

	arr = [ 1.0, 2.0, 3.0 ];
	out = Float64Array.from( arr, mapFn );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.strictEqual( out.length, 3, 'returns expected value' );
	t.strictEqual( out[ 0 ], 2.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 4.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 6.0, 'returns expected value' );
	t.end();

	function mapFn( v ) {
		return v * 2.0;
	}
});

tape( 'the method supports providing an execution context for the map function', function test( t ) {
	var ctx;
	var arr;
	var out;

	arr = [ 1.0, 2.0, 3.0 ];
	ctx = {
		'multiplier': 3.0
	};
	out = Float64Array.from( arr, mapFn, ctx );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.strictEqual( out.length, 3, 'returns expected value' );
	t.strictEqual( out[ 0 ], 3.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 6.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 9.0, 'returns expected value' );
	t.end();

	function mapFn( v ) {
		return v * this.multiplier; // eslint-disable-line no-invalid-this
	}
});
